  3248  check_called_node_in_look_behind(Node* node, int not)
  3249  {
  3250    int r;
  3251
  3252    r = 0;
  3253
  3254    switch (NODE_TYPE(node)) {
  3255    case NODE_LIST:
  3256    case NODE_ALT:
  3257      do {
  3258        r = check_called_node_in_look_behind(NODE_CAR(node), not);
  3259      } while (r == 0 && IS_NOT_NULL(node = NODE_CDR(node)));
  3260      break;
  3261
  3262    case NODE_QUANT:
  3263      r = check_called_node_in_look_behind(NODE_BODY(node), not);
  3264      break;
  3265
  3266    case NODE_BAG:
  3267      {
  3268        BagNode* en = BAG_(node);
  3269
  3270        if (en->type == BAG_MEMORY) {
  3271          if (NODE_IS_MARK1(node))
  3272            return 0;
  3273          else {
  3274            NODE_STATUS_ADD(node, MARK1);
  3275            r = check_called_node_in_look_behind(NODE_BODY(node), not);
  3276            NODE_STATUS_REMOVE(node, MARK1);
  3277          }
  3278        }
  3279        else {
  3280          r = check_called_node_in_look_behind(NODE_BODY(node), not);
  3281          if (r == 0 && en->type == BAG_IF_ELSE) {
  3282            if (IS_NOT_NULL(en->te.Then)) {
  3283              r = check_called_node_in_look_behind(en->te.Then, not);
  3284              if (r != 0) break;
  3285            }
  3286            if (IS_NOT_NULL(en->te.Else)) {
  3287              r = check_called_node_in_look_behind(en->te.Else, not);
  3288            }
  3289          }
