  3333  static int
  3334  check_node_in_look_behind(Node* node, int not)
  3335  {
  3336    static unsigned int
  3337      bag_mask[2] = { ALLOWED_BAG_IN_LB, ALLOWED_BAG_IN_LB_NOT };
  3338
  3339    static unsigned int
  3340      anchor_mask[2] = { ALLOWED_ANCHOR_IN_LB, ALLOWED_ANCHOR_IN_LB_NOT };
  3341
  3342    NodeType type;
  3343    int r = 0;
  3344
  3345    type = NODE_TYPE(node);
  3346    if ((NODE_TYPE2BIT(type) & ALLOWED_TYPE_IN_LB) == 0)
  3347      return 1;
  3348
  3349    switch (type) {
  3350    case NODE_LIST:
  3351    case NODE_ALT:
  3352      do {
  3353        r = check_node_in_look_behind(NODE_CAR(node), not);
  3354      } while (r == 0 && IS_NOT_NULL(node = NODE_CDR(node)));
  3355      break;
  3356
  3357    case NODE_QUANT:
  3358      r = check_node_in_look_behind(NODE_BODY(node), not);
  3359      break;
  3360
  3361    case NODE_BAG:
  3362      {
  3363        BagNode* en = BAG_(node);
  3364        if (((1<<en->type) & bag_mask[not]) == 0)
  3365          return 1;
  3366
  3367        r = check_node_in_look_behind(NODE_BODY(node), not);
  3368        if (r == 0 && en->type == BAG_IF_ELSE) {
  3369          if (IS_NOT_NULL(en->te.Then)) {
  3370            r = check_node_in_look_behind(en->te.Then, not);
  3371            if (r != 0) break;
  3372          }
  3373          if (IS_NOT_NULL(en->te.Else)) {
  3374            r = check_node_in_look_behind(en->te.Else, not);
  3375          }
  3376        }
  3377      }
  3378      break;
  3379
  3380    case NODE_ANCHOR:
  3381      type = ANCHOR_(node)->type;
  3382      if ((type & anchor_mask[not]) == 0)
  3383        return 1;
  3384
  3385      if (IS_NOT_NULL(NODE_BODY(node)))
  3386        r = check_node_in_look_behind(NODE_BODY(node), not);
  3387      break;
  3388
  3389    case NODE_GIMMICK:
  3390      if (NODE_IS_ABSENT_WITH_SIDE_EFFECTS(node) != 0)
  3391        return 1;
  3392      break;
  3393
  3394    case NODE_CALL:
  3395      r = check_called_node_in_look_behind(NODE_BODY(node), not);
  3396      break;
  3397
  3398    default:
  3399      break;
  3400    }
  3401    return r;
